import { test } from '@playwright/test';
// eslint-disable-next-line @typescript-eslint/no-require-imports
const z85 = require('z85');

test('probe', async ({ request }) => {
  const v = await (await request.get('/rest/admin/application-version')).json();
  console.log(JSON.stringify(v));
  const prods = (await (await request.get('/rest/products/search?q=')).json()).data;
  for (const p of prods) console.log(p.id, p.name, p.price, p.deluxePrice);
  const del = await (await request.get('/api/Deliverys')).json();
  console.log(JSON.stringify(del.data));

  const email = `probe-${Date.now()}@example.test`;
  const password = 'Passw0rd!probe';
  const u = await request.post('/api/Users', { data: { email, password, passwordRepeat: password, securityQuestion: { id: 1 }, securityAnswer: 'x' } });
  console.log('user', u.status(), await u.text());
  const l = await (await request.post('/rest/user/login', { data: { email, password } })).json();
  const { token, bid } = l.authentication;
  const h = { Authorization: `Bearer ${token}` };
  const egg = prods.find((p: { name: string }) => p.name === 'Eggfruit Juice (500ml)');
  const carrot = prods.find((p: { name: string }) => p.name === 'Carrot Juice (1000ml)');
  let r = await request.post('/api/BasketItems', { headers: h, data: { ProductId: egg.id, BasketId: String(bid), quantity: 2 } });
  console.log('bi', r.status(), await r.text());
  r = await request.post('/api/BasketItems', { headers: h, data: { ProductId: carrot.id, BasketId: String(bid), quantity: 1 } });
  console.log('bi', r.status(), await r.text());
  r = await request.post('/api/Addresss', { headers: h, data: { country: 'Ukraine', fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv' } });
  const addr = await r.json();
  console.log('addr', r.status(), JSON.stringify(addr));
  r = await request.post('/api/Cards', { headers: h, data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 } });
  const card = await r.json();
  console.log('card', r.status(), JSON.stringify(card));
  r = await request.put('/rest/wallet/balance', { headers: h, data: { balance: 5, paymentId: card.data.id } });
  console.log('wallet put', r.status(), await r.text());
  r = await request.get('/rest/wallet/balance', { headers: h });
  console.log('wallet get', r.status(), await r.text());
  const now = new Date();
  const mmm = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][now.getMonth()];
  const code = z85.encode(Buffer.from(`${mmm}${String(now.getFullYear()).slice(2)}-10`));
  console.log('code', code);
  r = await request.put(`/rest/basket/${bid}/coupon/${encodeURIComponent(code)}`, { headers: h });
  console.log('coupon', r.status(), await r.text());
  r = await request.get(`/rest/basket/${bid}`, { headers: h });
  console.log('basket', r.status(), await r.text());
  r = await request.post(`/rest/basket/${bid}/checkout`, { headers: h, data: { couponData: Buffer.from(`${code}-${Date.now()}`).toString('base64'), orderDetails: { paymentId: card.data.id, addressId: addr.data.id, deliveryMethodId: 1 } } });
  console.log('checkout', r.status(), await r.text());
  r = await request.get('/rest/order-history', { headers: h });
  console.log('history', r.status(), await r.text());
});

