await (async (page) => {
  const clean = s => s.replace(/<!---->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').replace(/<svg[\s\S]*?<\/svg>/g,'<svg/>').replace(/<span class="mat-(mdc-button-persistent-ripple|focus-indicator|mdc-button-touch-target)[^"]*"><\/span>/g,'').replace(/ (class|mat-ripple-loader[a-z-]*)="[^"]*"/g,'').replace(/<span><\/span>/g,'');
  await page.locator('mat-row').filter({ hasText: 'One Day Delivery' }).locator('mat-radio-button').click();
  await page.getByRole('button', { name: 'Proceed to delivery method selection' }).click();
  await page.waitForURL(/payment\/shop/);
  await page.locator('mat-row').first().waitFor();
  await page.waitForTimeout(800);
  const pay = clean(await page.locator('app-payment').evaluate(e => e.outerHTML));
  return { url: page.url(), pay: pay.slice(0, 14000) };
})(page);
```
