async (page) => {
  const out = {};
  await page.locator('#collapseCouponElement mat-expansion-panel-header').click();
  for (const code of ['abcdefghij', 'q:<Irhz3Tq', 'pEw8phz3Tq']) {
    await page.locator('#coupon').fill(code);
    await page.locator('#applyCouponButton').click();
    await page.waitForTimeout(1500);
    out[code] = await page.locator('#collapseCouponElement').evaluate(e => {
      const t = e.querySelectorAll('.error, .confirmation, [class*=error], [class*=confirm]');
      return Array.from(t).map(x => x.className + ' :: ' + x.textContent.trim());
    });
    out[code + '_snack'] = await page.locator('.mat-mdc-snack-bar-container').allInnerTexts();
    out[code + '_input'] = await page.locator('#coupon').inputValue();
  }
  out.walletHtml = await page.getByText('Wallet Balance').locator('xpath=ancestor::div[3]').evaluate(e => e.outerHTML.replace(/<!---->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').replace(/<svg[\s\S]*?<\/svg>/g,'')).catch(e => String(e));
  return out;
}

