    const l = await (await fetch('/rest/user/login', {method:'POST', headers:h, body: JSON.stringify({email, password})})).json();
    localStorage.setItem('token', l.authentication.token);
    sessionStorage.setItem('bid', String(l.authentication.bid));
    document.cookie = 'token=' + l.authentication.token + '; path=/';
    return l.authentication;
  }, {email, password});
  await page.goto('http://localhost:3000/#/order-history');
  await page.waitForTimeout(2000);
  const hist = (await page.locator('app-order-history').innerHTML()).replace(/<!---->/g,'').replace(/ _ngcontent-[^=]+=""/g,'').replace(/ class="[^"]*"/g,'').slice(0, 2000);
  await page.goto('http://localhost:3000/#/search');
  const art = page.locator('article').filter({ hasText: 'Apple Juice (1000ml)' });
  await art.getByRole('button', { name: 'Add to Basket' }).click();
  await page.waitForTimeout(1500);
  await page.goto('http://localhost:3000/#/basket');
  const row = page.locator('mat-row').filter({ hasText: 'Apple Juice (1000ml)' });
  await row.waitFor();
  const msgs = [];
  for (let i = 0; i < 5; i++) {
    await row.locator('button').nth(1).click();
    await page.waitForTimeout(1200);
    msgs.push({ q: await row.locator('.mat-column-quantity').innerText(), total: await page.locator('#price').innerText(), counter: await page.locator('.fa-layers-counter').innerText(), snack: await page.locator('.mat-mdc-snack-bar-container').allInnerTexts(), err: await page.locator('app-basket .error, app-basket .confirmation').allInnerTexts() });
  }
  await page.goto('http://localhost:3000/#/search');
  await art.getByRole('button', { name: 'Add to Basket' }).click();
  await page.waitForTimeout(1500);
  const snack = await page.locator('.mat-mdc-snack-bar-container').evaluateAll(es => es.map(e => e.className + ' :: ' + e.innerText));
  const counter = await page.locator('.fa-layers-counter').innerText();
  return { hist, msgs, snack, counter };
}

