import { encode } from 'z85';

/**
 * Coupon codes of test-cases/README.md: the Z85 encoding of `<MMM><YY>-<NN>`.
 * The server checks the month in its local time, and the tests run on the same machine,
 * so the code uses the local date of this machine.
 */
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;

function couponCodeForMonth(monthDate: Date, discountPercent: number): string {
  const month = MONTHS[monthDate.getMonth()];
  const year = String(monthDate.getFullYear()).slice(-2);
  const discount = String(discountPercent).padStart(2, '0');
  const code = encode(`${month}${year}-${discount}`);
  if (!code) throw new Error(`Cannot encode a coupon for ${month}${year}-${discount}`);
  return code;
}

export function currentMonthCouponCode(discountPercent: number, now = new Date()): string {
  return couponCodeForMonth(now, discountPercent);
}

export function previousMonthCouponCode(discountPercent: number, now = new Date()): string {
  return couponCodeForMonth(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
}

