import { BasketLine, OrderTotals } from '@/utils/types/shop';

/**
 * Expected values of the basket and the order, calculated from the catalog prices.
 * The coupon discount applies to the items only, not to the delivery.
 */
const CENTS = 100;
const BONUS_POINT_DIVISOR = 10;

const roundToCents = (amount: number): number => Math.round(amount * CENTS) / CENTS;

export function basketItemCount(lines: BasketLine[]): number {
  return lines.reduce((count, line) => count + line.quantity, 0);
}

export function itemsTotal(lines: BasketLine[]): number {
  return roundToCents(lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0));
}

export function orderTotals(lines: BasketLine[], deliveryPrice: number, discountPercent = 0): OrderTotals {
  const items = itemsTotal(lines);
  const promotion = roundToCents((items * discountPercent) / CENTS);
  return { items, delivery: deliveryPrice, promotion, total: roundToCents(items - promotion + deliveryPrice) };
}

/** Bonus points of one product: price / 10, rounded to a whole number, × quantity. */
export function bonusPoints(lines: BasketLine[]): number {
  return lines.reduce((points, line) => points + Math.round(line.product.price / BONUS_POINT_DIVISOR) * line.quantity, 0);
}

