/** How the UI prints money. The shop uses the sign `¤`. */
export const CURRENCY_SIGN = '¤';

const PRICE_DECIMALS = 2;
const BASKET_TOTAL_MAX_DECIMALS = 3;

/** `8.99¤`, `0.00¤`: product, delivery and order summary prices. */
export function formatPrice(amount: number): string {
  return `${formatAmount(amount)}${CURRENCY_SIGN}`;
}

/** `5.00`: the wallet balance, printed without the sign. */
export function formatAmount(amount: number): string {
  return amount.toFixed(PRICE_DECIMALS);
}

/** `17.98¤`, `0¤`: the basket total uses the Angular `number` pipe, without trailing zeros. */
export function formatBasketTotal(amount: number): string {
  const text = amount.toLocaleString('en-US', { maximumFractionDigits: BASKET_TOTAL_MAX_DECIMALS });
  return `${text}${CURRENCY_SIGN}`;
}

