  await expect(locator, `${description} does not contain ${String(text)}`).not.toContainText(text);
}

export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
  await expect(locator, `${description}: count is ${count}`).toHaveCount(count);
}

export async function expectEnabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is enabled`).toBeEnabled();
}

export async function expectDisabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is disabled`).toBeDisabled();
}

