import { APIRequestContext, APIResponse } from '@playwright/test';
import { Customer } from '@/utils/types/shop';

export const HTTP_STATUS = {
  ok: 200,
  created: 201,
} as const;

/** Base of the API clients: request context, the customer token header, status checks. */
export abstract class ApiClient {
  constructor(protected readonly request: APIRequestContext) {}

  protected authHeaders(customer: Customer): Record<string, string> {
    return { Authorization: `Bearer ${customer.token}` };
  }

  protected async readJson<T>(response: APIResponse, expectedStatus: number, action: string): Promise<T> {
    if (response.status() !== expectedStatus) {
      throw new Error(
        `${action}: expected HTTP ${expectedStatus}, got ${response.status()} ${await response.text()}`,
      );
    }
    return (await response.json()) as T;
  }
}

