import { ApiClient, HTTP_STATUS } from '@/core/api/api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import { Customer } from '@/utils/types/shop';

interface LoginResponse {
  authentication: { token: string; bid: number; umail: string };
}

export class UsersApi extends ApiClient {
  /** POST /api/Users creates a normal customer account (role `customer`). */
  async register(email: string, password: string): Promise<void> {
    const response = await this.request.post(API_ROUTES.users, {
      data: { email, password, passwordRepeat: password },
    });
    await this.readJson<unknown>(response, HTTP_STATUS.created, `Register ${email}`);
  }

  async login(email: string, password: string): Promise<Customer> {
    const response = await this.request.post(API_ROUTES.login, { data: { email, password } });
    const body = await this.readJson<LoginResponse>(response, HTTP_STATUS.ok, `Log in ${email}`);
    return { email, password, token: body.authentication.token, basketId: body.authentication.bid };
  }
}

