import { ApiClient, HTTP_STATUS } from '@/core/api/api-client';
import { API_ROUTES } from '@/utils/constants/routes';

interface ProductSearchResponse {
  data: Array<{ id: number; name: string }>;
}

export class ProductsApi extends ApiClient {
  async findProductId(name: string): Promise<number> {
    const response = await this.request.get(API_ROUTES.productSearch, { params: { q: name } });
    const body = await this.readJson<ProductSearchResponse>(response, HTTP_STATUS.ok, `Search ${name}`);
    const product = body.data.find((item) => item.name === name);
    if (!product) throw new Error(`The catalog has no product ${name}`);
    return product.id;
  }
}

