import { API_ROUTES } from '@/utils/constants/routes';
import { Customer, SavedAddress, SavedCard } from '@/utils/types/shop';

interface CreatedResponse {
  data: { id: number };
}

/** Saved addresses, saved cards and the wallet of a customer. */
export class PaymentApi extends ApiClient {
  async saveAddress(customer: Customer, address: SavedAddress): Promise<number> {
    const response = await this.request.post(API_ROUTES.addresses, {
      headers: this.authHeaders(customer),
      data: {
        country: address.country,
        fullName: address.fullName,
        mobileNum: address.mobileNumber,
        zipCode: address.zipCode,
        streetAddress: address.streetAddress,
        city: address.city,
        state: address.state,
      },
    });
    const body = await this.readJson<CreatedResponse>(response, HTTP_STATUS.created, 'Save an address');
    return body.data.id;
  }

  async saveCard(customer: Customer, card: SavedCard): Promise<number> {
    const response = await this.request.post(API_ROUTES.cards, {
      headers: this.authHeaders(customer),
      data: {
        fullName: card.fullName,
        cardNum: card.cardNumber,
        expMonth: card.expiryMonth,
        expYear: card.expiryYear,
      },
    });
    const body = await this.readJson<CreatedResponse>(response, HTTP_STATUS.created, 'Save a card');
    return body.data.id;
  }

  /** The shop adds money to the wallet only from a saved card of the customer. */
  async topUpWallet(customer: Customer, amount: number, cardId: number): Promise<void> {
    const response = await this.request.put(API_ROUTES.walletBalance, {
      headers: this.authHeaders(customer),
      data: { balance: amount, paymentId: cardId },
    });
    await this.readJson<unknown>(response, HTTP_STATUS.ok, `Add ${amount} to the wallet`);
  }
}

