import { expectContainText, expectHidden, expectNotContainText, expectVisible } from '@/utils/assertions/ui-assertions';

/** The menu under the button `Account`, with the submenu `Orders & Payment`. */
export class AccountMenuComponent {
  private readonly menu: Locator;
  private readonly loginItem: Locator;
  private readonly logoutItem: Locator;
  private readonly profileItem: Locator;
  private readonly ordersAndPaymentItem: Locator;
  private readonly orderHistoryItem: Locator;
  private readonly digitalWalletItem: Locator;

  constructor(page: Page) {
    this.menu = page.locator('.mat-mdc-menu-panel').first();
    this.loginItem = page.locator('#navbarLoginButton');
    this.logoutItem = page.locator('#navbarLogoutButton');
    this.profileItem = page.getByRole('menuitem', { name: 'Go to user profile' });
    this.ordersAndPaymentItem = page.getByRole('menuitem', { name: 'Show Orders and Payment Menu' });
    this.orderHistoryItem = page.getByRole('menuitem', { name: 'Go to order history page' });
    this.digitalWalletItem = page.getByRole('menuitem', { name: 'Go to wallet page' });
  }

  async shouldSeeMenu(): Promise<void> {
    await expectVisible(this.menu, 'Account menu');
  }

  async shouldNotSeeMenu(): Promise<void> {
    await expectHidden(this.menu, 'Account menu');
  }

  async shouldSeeLoginItem(): Promise<void> {
    await expectVisible(this.loginItem, 'Account menu item `Login`');
    await expectContainText(this.loginItem, UI_TEXTS.accountMenuLogin, 'Account menu item `Login`');
  }

  async shouldNotSeeEmail(email: string): Promise<void> {
    await expectNotContainText(this.menu, email, 'Account menu');
  }

  async shouldSeeEmail(email: string): Promise<void> {
    await expectContainText(this.profileItem, email, 'Account menu item with the email');
  }

  async shouldSeeLogoutItem(): Promise<void> {
    await expectVisible(this.logoutItem, 'Account menu item `Logout`');
    await expectContainText(this.logoutItem, UI_TEXTS.accountMenuLogout, 'Account menu item `Logout`');
  }

  async clickOrderHistory(): Promise<void> {
    await this.ordersAndPaymentItem.click();
    await this.orderHistoryItem.click();
  }

  async clickDigitalWallet(): Promise<void> {
    await this.ordersAndPaymentItem.click();
    await this.digitalWalletItem.click();
  }
}

