import { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { API_ROUTES, UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXTS } from '@/utils/constants/ui-texts';
import { formatPrice } from '@/utils/helpers/price-format';
import { CatalogProduct } from '@/utils/types/shop';
import { expectContainText, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';

const SEARCH_URL = /#\/search/;

/** The product list `/#/search`. */
export class SearchPage extends BasePage {
  private readonly productCards: Locator;

  constructor(page: Page) {
    super(page);
    this.productCards = page.locator('app-search-result article.product');
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.search);
    await this.shouldSeePage();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, SEARCH_URL, 'Product list');
    await expectVisible(this.productCards.first(), 'First product card');
  }

  async shouldSeeProduct(product: CatalogProduct): Promise<void> {
    const card = this.productCard(product.name);
    await expectVisible(card, `Product card ${product.name}`);
    await expectText(card.locator('.name'), product.name, `Name on the card ${product.name}`);
    await expectText(card.locator('.price'), formatPrice(product.price), `Price on the card ${product.name}`);
    await expectVisible(this.addToBasketButton(product.name), `Button \`Add to Basket\` on ${product.name}`);
    await expectContainText(this.addToBasketButton(product.name), UI_TEXTS.addToBasket, `Button on ${product.name}`);
  }

  /** Clicks `Add to Basket` and waits until the server answers the basket update. */
  async clickAddToBasket(productName: string): Promise<void> {
    const basketUpdate = this.page.waitForResponse(
      (response) =>
        response.url().includes(API_ROUTES.basketItems) && ['POST', 'PUT'].includes(response.request().method()),
    );
    await this.addToBasketButton(productName).click();
    await basketUpdate;
  }

  private productCard(productName: string): Locator {
    return this.productCards.filter({ has: this.page.locator('.name', { hasText: productName }) });
  }

  private addToBasketButton(productName: string): Locator {
    return this.productCard(productName).getByRole('button', { name: UI_TEXTS.addToBasket });
  }
}

