import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';

const ADDRESS_SELECT_URL = /#\/address\/select/;

/** Checkout step `Select an address`. */
export class AddressSelectPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly continueButton: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.locator('app-address h1');
    this.rows = page.locator('app-address mat-row');
    this.continueButton = page.getByRole('button', { name: 'Proceed to payment selection' });
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, ADDRESS_SELECT_URL, 'Address selection page');
    await expectText(this.title, UI_TEXTS.selectAddressTitle, 'Address selection title');
  }

  async shouldSeeSavedAddress(address: SavedAddress): Promise<void> {
    const row = this.row(address);
    await expectVisible(row, `Saved address of ${address.fullName}`);
    await expectText(row.locator('mat-cell.mat-column-Name'), address.fullName, 'Address name');
    await expectText(row.locator('mat-cell.mat-column-Address'), formatAddressLine(address), 'Address line');
    await expectText(row.locator('mat-cell.mat-column-Country'), address.country, 'Address country');
  }

  async selectAddress(address: SavedAddress): Promise<void> {
    await this.row(address).locator('mat-radio-button').click();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  private row(address: SavedAddress): Locator {
    return this.rows.filter({ hasText: address.streetAddress });
  }
}

