  async selectDeliveryMethod(methodName: string): Promise<void> {
    await this.row(methodName).locator('mat-radio-button').click();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  private row(methodName: string): Locator {
    return this.rows.filter({ hasText: methodName });
  }
}

