import { Locator, Page } from '@playwright/test';
import { cardLastDigits } from '@/utils/helpers/address-format';
import { SavedCard } from '@/utils/types/shop';
import { expectContainText, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

const MASKED_DIGITS = '************';

/** The list of saved cards on the payment page. */
export class SavedCardsComponent {
  private readonly rows: Locator;

  constructor(page: Page) {
    this.rows = page.locator('app-payment-method mat-row');
  }

  async shouldSeeCard(card: SavedCard): Promise<void> {
    const row = this.row(card);
    await expectVisible(row, 'Saved card');
    await expectText(row.locator('mat-cell').nth(1), `${MASKED_DIGITS}${cardLastDigits(card)}`, 'Masked card number');
    await expectText(row.locator('mat-cell').nth(2), card.fullName, 'Card holder');
    await expectContainText(row, `${card.expiryMonth}/${card.expiryYear}`, 'Card expiry');
  }

  async selectCard(card: SavedCard): Promise<void> {
    await this.row(card).locator('mat-radio-button').click();
  }

  private row(card: SavedCard): Locator {
    return this.rows.filter({ hasText: `${MASKED_DIGITS}${cardLastDigits(card)}` });
  }
}

