import { Locator, Page } from '@playwright/test';
import { formatAmount, formatPrice } from '@/utils/helpers/price-format';
import { expectDisabled, expectEnabled, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

/** The block `Pay using wallet` on the payment page: the balance and the button `Pay <amount>¤`. */
export class WalletPaymentComponent {
  private readonly block: Locator;
  private readonly balance: Locator;
  private readonly payButton: Locator;

  constructor(page: Page) {
    this.block = page.locator('app-payment .custom-card').filter({ hasText: 'Wallet Balance' });
    this.balance = this.block.locator('.confirmation');
    this.payButton = this.block.getByRole('button', { name: /Pay/ });
  }

  async shouldSeeBalance(amount: number): Promise<void> {
    await expectVisible(this.balance, 'Wallet balance on the payment page');
    await expectText(this.balance, formatAmount(amount), 'Wallet balance on the payment page');
  }

  async shouldSeePayButton(amount: number): Promise<void> {
    await expectVisible(this.payButton, 'Button `Pay`');
    await expectText(this.payButton, `Pay ${formatPrice(amount)}`, 'Button `Pay`');
  }

  async shouldSeePayButtonDisabled(): Promise<void> {
    await expectDisabled(this.payButton, 'Button `Pay`');
  }

  async shouldSeePayButtonEnabled(): Promise<void> {
    await expectEnabled(this.payButton, 'Button `Pay`');
  }

  async clickPay(): Promise<void> {
    await this.payButton.click();
  }
}

