import { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CouponPanelComponent } from '@/page-objects/components/coupon-panel.component';
import { SavedCardsComponent } from '@/page-objects/components/saved-cards.component';
import { WalletPaymentComponent } from '@/page-objects/components/wallet-payment.component';
import { UI_TEXTS } from '@/utils/constants/ui-texts';
import { SavedCard } from '@/utils/types/shop';
import { expectText, expectUrl } from '@/utils/assertions/ui-assertions';

