  constructor(page: Page) {
    super(page);
    this.confirmationTitle = page.locator('app-order-completion h1');
    this.productRows = page.locator('app-order-completion mat-row');
    const footerCells = page.locator('app-order-completion mat-footer-row mat-footer-cell');
    this.totalLabels = footerCells.nth(TOTAL_LABELS.length - 2).locator('td');
    this.totalValues = footerCells.nth(TOTAL_LABELS.length - 1).locator('td');
