    const match = ORDER_COMPLETION_URL.exec(this.page.url());
    if (!match) throw new Error(`No order ID in the URL ${this.page.url()}`);
    return match[1];
  }

  /** Each product row: name, unit price, quantity, line total. */
  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.productRows, lines.length, 'Confirmation product rows');
    for (const line of lines) {
      const cells = this.productRows.filter({ hasText: line.product.name }).locator('mat-cell');
      await expectText(
        cells,
        [line.product.name, formatPrice(line.product.price), String(line.quantity), formatPrice(line.product.price * line.quantity)],
        `Confirmation row ${line.product.name}`,
