  orderId: string;
  totalPrice: number;
  bonus?: number;
  lines?: BasketLine[];
}

/** The page `Order History`. Each order is a block with a heading (ID, total, bonus) and a product table. */
export class OrderHistoryPage extends BasePage {
  private readonly title: Locator;
  private readonly orders: Locator;
  private readonly emptyMessage: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.locator('app-order-history mat-card-title').first();
    this.orders = page.locator('app-order-history .table-container');
    this.emptyMessage = page.locator('app-order-history mat-card-content');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, ORDER_HISTORY_URL, 'Order history page');
    await expectText(this.title, UI_TEXTS.orderHistoryTitle, 'Order history title');
  }

  async shouldSeeEmptyHistory(): Promise<void> {
    await expectVisible(this.emptyMessage, 'Empty order history message');
    await expectText(this.emptyMessage, UI_TEXTS.orderHistoryEmpty, 'Empty order history message');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.orders, count, 'Orders in the history');
  }

  async shouldSeeOrder(order: ExpectedOrder): Promise<void> {
    const block = this.orders.filter({ hasText: `#${order.orderId}` });
    await expectVisible(block, `Order #${order.orderId}`);
    await expectText(this.headingValue(block, 'Total Price'), formatPrice(order.totalPrice), `Total of order #${order.orderId}`);
    if (order.bonus !== undefined) {
      await expectText(this.headingValue(block, 'Bonus'), String(order.bonus), `Bonus of order #${order.orderId}`);
    }
    for (const line of order.lines ?? []) {
      const row = block.locator('mat-row').filter({ hasText: line.product.name });
      await expectContainText(row.locator('mat-cell.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
    }
    if (order.lines) await expectCount(block.locator('mat-row'), order.lines.length, `Products of order #${order.orderId}`);
  }

  private headingValue(block: Locator, label: string): Locator {
    return block.locator('.col-vertical').filter({ hasText: label }).locator('div').nth(1);
  }
}

