import { randomUUID } from 'node:crypto';
import { ShopApi } from '@/core/api/shop-api';
import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
import { Customer, CustomerSetup } from '@/utils/types/shop';

/**
 * New customer accounts for tests: one unique account per test, created through the API,
 * with an optional basket, saved address and card, and wallet balance.
 */
const EMAIL_DOMAIN = 'example.test';
const UNIQUE_PART_LENGTH = 8;

function uniquePart(): string {
  return `${Date.now()}-${randomUUID().slice(0, UNIQUE_PART_LENGTH)}`;
}

export async function createCustomer(api: ShopApi, emailPrefix = 'customer'): Promise<Customer> {
  const unique = uniquePart();
  const email = `${emailPrefix}-${unique}@${EMAIL_DOMAIN}`;
  const password = `Passw0rd!${unique}`;
  await api.users.register(email, password);
  return api.users.login(email, password);
}

export async function createPreparedCustomer(api: ShopApi, setup: CustomerSetup): Promise<Customer> {
  const customer = await createCustomer(api);
  for (const line of setup.basket ?? []) {
    const productId = await api.products.findProductId(line.product.name);
    await api.basket.addItem(customer, productId, line.quantity);
  }
  if (setup.savedAddressAndCard) {
    await api.payment.saveAddress(customer, SAVED_ADDRESS);
    customer.savedCardId = await api.payment.saveCard(customer, SAVED_CARD);
  }
  if (setup.walletBalance) {
    await addMoneyToWallet(api, customer, setup.walletBalance);
  }
  return customer;
}

export async function addMoneyToWallet(api: ShopApi, customer: Customer, amount: number): Promise<void> {
  if (customer.savedCardId === undefined) {
    throw new Error('The shop adds money to the wallet only with a saved card. Set savedAddressAndCard first.');
  }
  await api.payment.topUpWallet(customer, amount, customer.savedCardId);
}

