import { AddressSelectPage } from '@/page-objects/address-select-page';
import { BasketPage } from '@/page-objects/basket-page';
import { DeliveryMethodPage } from '@/page-objects/delivery-method-page';
import { SavedAddress } from '@/utils/types/shop';

/**
 * Checkout steps that several specs repeat: from the basket to the delivery step,
 * and from the delivery step to the payment step.
 */
export async function checkoutWithSavedAddress(
  basketPage: BasketPage,
  addressSelectPage: AddressSelectPage,
  address: SavedAddress,
): Promise<void> {
  await basketPage.open();
  await basketPage.clickCheckout();
  await addressSelectPage.shouldSeePage();
  await addressSelectPage.selectAddress(address);
  await addressSelectPage.clickContinue();
}

export async function chooseDeliveryMethod(deliveryMethodPage: DeliveryMethodPage, methodName: string): Promise<void> {
  await deliveryMethodPage.selectDeliveryMethod(methodName);
  await deliveryMethodPage.clickContinue();
}

