import { createCustomer } from '@/core/api/customer-factory';
import { test } from '@/fixtures/pages.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';

test('Login with a wrong password fails and with the right password opens the shop', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.auth],
  annotation: { type: 'test-case', description: 'TC-01' },
}, async ({ api, loginPage, searchPage }) => {
  const customer = await test.step('Precondition: create a customer account, nobody is logged in', async () => {
    return createCustomer(api, 'login');
  });
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await loginPage.open();
    await loginPage.shouldSeePage();
  });

  await test.step('2. Log in with the email and the wrong password', async () => {
    await loginPage.login(customer.email, wrongPassword);
    await loginPage.shouldSeeInvalidCredentialsError();
  });

  await test.step('3. Open the account menu', async () => {
    await loginPage.navbar.openAccountMenu();
    await loginPage.navbar.accountMenu.shouldSeeLoginItem();
    await loginPage.navbar.accountMenu.shouldNotSeeEmail(customer.email);
  });

  await test.step('4. Close the menu and log in with the correct password', async () => {
    await loginPage.navbar.closeAccountMenu();
    await loginPage.login(customer.email, customer.password);
    await loginPage.shouldBeRedirectedToProductList();
    await searchPage.shouldSeePage();
  });

  await test.step('5. Open the account menu', async () => {
    await searchPage.navbar.openAccountMenu();
    await searchPage.navbar.accountMenu.shouldSeeEmail(customer.email);
    await searchPage.navbar.accountMenu.shouldSeeLogoutItem();
  });
});

