import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/shop-data';
import { UI_TEXTS } from '@/utils/constants/ui-texts';
import { basketItemCount, itemsTotal } from '@/utils/helpers/order-math';
import { BasketLine } from '@/utils/types/shop';

const product = PRODUCTS.eggfruitJuice;
const basketAfterAdd: BasketLine[] = [{ product, quantity: 1 }];

test('Add a product to the empty basket from the product list', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-02' },
}, async ({ customer: _customer, searchPage, basketPage }) => {
  await test.step('1. Open the product list', async () => {
    await searchPage.open();
    await searchPage.shouldSeeProduct(product);
    await searchPage.navbar.shouldSeeBasketCount(0);
  });

  await test.step(`2. Click \`Add to Basket\` on ${product.name}`, async () => {
    await searchPage.clickAddToBasket(product.name);
    await searchPage.snackBar.shouldSeeConfirmation(UI_TEXTS.placedIntoBasket(product.name));
    await searchPage.navbar.shouldSeeBasketCount(basketItemCount(basketAfterAdd));
  });

  await test.step('3. Open the basket with the button `Your Basket`', async () => {
    await searchPage.navbar.clickYourBasket();
    await basketPage.shouldSeePage();
    await basketPage.shouldSeeLines(basketAfterAdd);
  });

  await test.step('4. Read the total of the basket', async () => {
    await basketPage.shouldSeeTotalPrice(itemsTotal(basketAfterAdd));
  });
});

