import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/shop-data';
import { basketItemCount, itemsTotal } from '@/utils/helpers/order-math';
import { BasketLine } from '@/utils/types/shop';

const productA = PRODUCTS.raspberryJuice;
const productB = PRODUCTS.eggfruitJuice;

const startBasket: BasketLine[] = [{ product: productA, quantity: 1 }, { product: productB, quantity: 1 }];
const basketWithTwoA: BasketLine[] = [{ product: productA, quantity: 2 }, { product: productB, quantity: 1 }];
const basketWithoutA: BasketLine[] = [{ product: productB, quantity: 1 }];

test.use({ customerSetup: { basket: startBasket } });

test('Change the quantity and remove a product in the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, async ({ basketPage }) => {
  await test.step('1. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeLines(startBasket);
    await basketPage.shouldSeeTotalPrice(itemsTotal(startBasket));
    await basketPage.navbar.shouldSeeBasketCount(basketItemCount(startBasket));
  });

  await test.step('2. Click the plus button in the row of product A', async () => {
    await basketPage.clickIncreaseQuantity(productA.name);
    await basketPage.shouldSeeLines(basketWithTwoA);
    await basketPage.shouldSeeTotalPrice(itemsTotal(basketWithTwoA));
    await basketPage.navbar.shouldSeeBasketCount(basketItemCount(basketWithTwoA));
  });

  await test.step('3. Click the minus button in the row of product A', async () => {
    await basketPage.clickDecreaseQuantity(productA.name);
    await basketPage.shouldSeeLines(startBasket);
    await basketPage.shouldSeeTotalPrice(itemsTotal(startBasket));
    await basketPage.navbar.shouldSeeBasketCount(basketItemCount(startBasket));
  });

  await test.step('4. Click the minus button in the row of product A again', async () => {
    await basketPage.clickDecreaseQuantity(productA.name);
    await basketPage.shouldKeepQuantity(productA.name, 1);
    await basketPage.shouldSeeLines(startBasket);
    await basketPage.shouldKeepTotalPrice(itemsTotal(startBasket));
  });

  await test.step('5. Click the trash button in the row of product A', async () => {
    await basketPage.clickRemove(productA.name);
    await basketPage.shouldNotSeeProduct(productA.name);
    await basketPage.shouldSeeLines(basketWithoutA);
    await basketPage.shouldSeeTotalPrice(itemsTotal(basketWithoutA));
    await basketPage.navbar.shouldSeeBasketCount(basketItemCount(basketWithoutA));
  });
});

