import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { COUPON_DISCOUNT_PERCENT, DELIVERY_METHODS, PRODUCTS, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
import { currentMonthCouponCode } from '@/utils/helpers/coupon-code';
import { orderTotals } from '@/utils/helpers/order-math';
import { BasketLine } from '@/utils/types/shop';

const basket: BasketLine[] = [{ product: PRODUCTS.eggfruitJuice, quantity: 2 }];
const delivery = DELIVERY_METHODS.oneDay;

test.use({ customerSetup: { basket, savedAddressAndCard: true } });

test('A valid coupon of the current month lowers the price of the items on the payment step', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-05' },
}, async ({ basketPage, addressSelectPage, deliveryMethodPage, paymentPage, orderSummaryPage }) => {
  await test.step('1. Open the basket and click `Checkout`', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressSelectPage.shouldSeePage();
    await addressSelectPage.shouldSeeSavedAddress(SAVED_ADDRESS);
  });

  await test.step('2. Select the saved address and continue', async () => {
    await addressSelectPage.selectAddress(SAVED_ADDRESS);
    await addressSelectPage.clickContinue();
    await deliveryMethodPage.shouldSeePage();
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.oneDay);
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.fast);
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.standard);
  });

  await test.step(`3. Select \`${delivery.name}\` and continue`, async () => {
    await deliveryMethodPage.selectDeliveryMethod(delivery.name);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeSavedCard(SAVED_CARD);
    await paymentPage.shouldSeeCouponPanel();
  });

  await test.step('4. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(currentMonthCouponCode(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponDiscountMessage(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('5. Select the saved card and continue', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeLines(basket);
    await orderSummaryPage.shouldSeeTotals(orderTotals(basket, delivery.price, COUPON_DISCOUNT_PERCENT));
  });
});

