import { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { UI_ROUTES } from '@/utils/constants/routes';
import { formatBasketTotal, formatPrice } from '@/utils/helpers/price-format';
import { BasketLine } from '@/utils/types/shop';
import {
  expectCount,
  expectDisabled,
  expectText,
  expectTextHeld,
  expectUrl,
  expectVisible,
} from '@/utils/assertions/ui-assertions';

const BASKET_URL = /#\/basket$/;
const TOTAL_PRICE_PREFIX = 'Total Price: ';

/** The basket `/#/basket`. Each row: image, name, minus / quantity / plus, unit price, trash. */
export class BasketPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.locator('app-purchase-basket h1');
    this.rows = page.locator('app-purchase-basket mat-row');
    this.totalPrice = page.locator('app-purchase-basket #price');
    this.checkoutButton = page.locator('app-basket #checkoutButton');
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.basket);
    await this.shouldSeePage();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, BASKET_URL, 'Basket page');
    await expectVisible(this.title, 'Basket title');
  }

  /** The basket shows exactly these rows, each with its quantity and unit price. */
  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.rows, lines.length, 'Basket rows');
    for (const line of lines) await this.shouldSeeLine(line);
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const row = this.row(line.product.name);
    await expectVisible(row, `Basket row ${line.product.name}`);
    await expectText(this.quantity(line.product.name), String(line.quantity), `Quantity of ${line.product.name}`);
    await expectText(row.locator('mat-cell.mat-column-price'), formatPrice(line.product.price), `Price of ${line.product.name}`);
  }

  /** The quantity is right and does not change during the hold window. */
  async shouldKeepQuantity(productName: string, quantity: number): Promise<void> {
    await expectTextHeld(this.quantity(productName), String(quantity), `Quantity of ${productName}`);
  }

  async shouldNotSeeProduct(productName: string): Promise<void> {
    await expectCount(this.row(productName), 0, `Basket rows of ${productName}`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.rows, 0, 'Basket rows');
  }

  async shouldSeeTotalPrice(amount: number): Promise<void> {
    await expectText(this.totalPrice, `${TOTAL_PRICE_PREFIX}${formatBasketTotal(amount)}`, 'Basket total');
  }

  async shouldKeepTotalPrice(amount: number): Promise<void> {
    await expectTextHeld(this.totalPrice, `${TOTAL_PRICE_PREFIX}${formatBasketTotal(amount)}`, 'Basket total');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
  }

  async clickIncreaseQuantity(productName: string): Promise<void> {
    await this.row(productName).locator('mat-cell.mat-column-quantity button').last().click();
  }

  async clickDecreaseQuantity(productName: string): Promise<void> {
    await this.row(productName).locator('mat-cell.mat-column-quantity button').first().click();
  }

  /** Clicks the plus button one time for each missing item, and waits for each new quantity. */
  async increaseQuantityTo(productName: string, from: number, to: number): Promise<void> {
    for (let quantity = from + 1; quantity <= to; quantity += 1) {
      await this.clickIncreaseQuantity(productName);
      await expectText(this.quantity(productName), String(quantity), `Quantity of ${productName}`);
    }
  }

  async clickRemove(productName: string): Promise<void> {
    await this.row(productName).locator('mat-cell.mat-column-remove button').click();
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  private row(productName: string): Locator {
    return this.rows.filter({ has: this.page.locator('mat-cell.mat-column-product', { hasText: productName }) });
  }

  private quantity(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-quantity span');
  }
}

import { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { UI_TEXTS } from '@/utils/constants/ui-texts';
import { cardLastDigits, formatAddressLine } from '@/utils/helpers/address-format';
import { formatPrice } from '@/utils/helpers/price-format';
import { BasketLine, OrderTotals, SavedAddress, SavedCard } from '@/utils/types/shop';
import { expectContainText, expectCount, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';

const ORDER_SUMMARY_URL = /#\/order-summary/;

/** Checkout step `Order Summary`, before the order is placed. */
export class OrderSummaryPage extends BasePage {
  private readonly title: Locator;
  private readonly addressCard: Locator;
  private readonly paymentCard: Locator;
  private readonly productRows: Locator;
  private readonly totalsTable: Locator;
  private readonly placeOrderButton: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.locator('app-order-summary .order-summary');
    this.addressCard = page.locator('app-order-summary mat-card').filter({ hasText: 'Delivery Address' }).last();
    this.paymentCard = page.locator('app-order-summary mat-card').filter({ hasText: 'Payment Method' }).last();
    this.productRows = page.locator('app-order-summary app-purchase-basket mat-row');
    this.totalsTable = page.locator('app-order-summary table');
    this.placeOrderButton = page.locator('app-order-summary #checkoutButton');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, ORDER_SUMMARY_URL, 'Order summary page');
    await expectText(this.title, UI_TEXTS.orderSummaryTitle, 'Order summary title');
  }

  async shouldSeeDeliveryAddress(address: SavedAddress): Promise<void> {
    await expectVisible(this.addressCard, 'Delivery address on the order summary');
    await expectContainText(this.addressCard, address.fullName, 'Delivery address name');
    await expectContainText(this.addressCard, formatAddressLine(address), 'Delivery address line');
    await expectContainText(this.addressCard, address.country, 'Delivery address country');
  }

  async shouldSeeCardPayment(card: SavedCard): Promise<void> {
    await expectVisible(this.paymentCard, 'Payment method on the order summary');
    await expectContainText(this.paymentCard, `${UI_TEXTS.cardEndingIn} ${cardLastDigits(card)}`, 'Card number');
    await expectContainText(this.paymentCard, card.fullName, 'Card holder');
  }

  async shouldSeeWalletPayment(): Promise<void> {
    await expectVisible(this.paymentCard, 'Payment method on the order summary');
    await expectContainText(this.paymentCard, UI_TEXTS.digitalWallet, 'Payment method');
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.productRows, lines.length, 'Order summary product rows');
    for (const line of lines) {
      const row = this.productRows.filter({ hasText: line.product.name });
      await expectText(row.locator('mat-cell.mat-column-quantity span'), String(line.quantity), `Quantity of ${line.product.name}`);
      await expectText(row.locator('mat-cell.mat-column-price'), formatPrice(line.product.price), `Price of ${line.product.name}`);
    }
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await this.shouldSeeTotalLine('Items', totals.items);
    await this.shouldSeeTotalLine('Delivery', totals.delivery);
    await this.shouldSeeTotalLine('Promotion', totals.promotion);
    await this.shouldSeeTotalLine('Total Price', totals.total);
  }

  async shouldSeeTotalPrice(amount: number): Promise<void> {
    await this.shouldSeeTotalLine('Total Price', amount);
  }

  async clickPlaceOrder(): Promise<void> {
    await this.placeOrderButton.click();
  }

  private async shouldSeeTotalLine(label: string, amount: number): Promise<void> {
    const row = this.totalsTable.locator('tr').filter({ has: this.page.locator('td.label', { hasText: new RegExp(`^\\s*${label}\\s*$`) }) });
    await expectText(row.locator('td.price'), formatPrice(amount), `Order summary line ${label}`);
  }
}

import { createCustomer } from '@/core/api/customer-factory';
import { test } from '@/fixtures/pages.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';

test('Login with a wrong password fails and with the right password opens the shop', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.auth],
  annotation: { type: 'test-case', description: 'TC-01' },
}, async ({ api, loginPage, searchPage }) => {
  const customer = await test.step('Precondition: create a customer account, nobody is logged in', async () => {
    return createCustomer(api, 'login');
  });
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await loginPage.open();
    await loginPage.shouldSeePage();
  });

  await test.step('2. Log in with the email and the wrong password', async () => {
    await loginPage.login(customer.email, wrongPassword);
