}, async ({
  api,
  customer,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
  walletPage,
}) => {
  // Two passes through the checkout take longer than the default 30 s.
  test.setTimeout(DateHelper.minutesToMs(2));
  let orderId = '';

  await test.step('1. Open the basket, check out and continue with the saved address', async () => {
    await checkoutWithSavedAddress(basketPage, addressSelectPage, SAVED_ADDRESS);
