    await paymentPage.shouldSeeWalletPayButtonDisabled();
  });

  await test.step('4. Open `Order History` from the account menu', async () => {
    await paymentPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeEmptyHistory();
  });

  await test.step('5. Open `Digital Wallet` from the account menu', async () => {
    await orderHistoryPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(WALLET_FIRST_BALANCE);
  });

  await test.step(`Precondition: add ${WALLET_TOP_UP} to the wallet with the saved card`, async () => {
    await addMoneyToWallet(api, customer, WALLET_TOP_UP);
  });

  await test.step(`6. Check out again with \`${delivery.name}\``, async () => {
    await checkoutWithSavedAddress(basketPage, addressSelectPage, SAVED_ADDRESS);
    await chooseDeliveryMethod(deliveryMethodPage, delivery.name);
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(balanceBeforeOrder);
    await paymentPage.shouldSeeWalletPayButton(orderTotal);
    await paymentPage.shouldSeeWalletPayButtonEnabled();
  });

  await test.step('7. Click `Pay`', async () => {
    await paymentPage.clickPayWithWallet();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeWalletPayment();
    await orderSummaryPage.shouldSeeTotalPrice(orderTotal);
  });

  await test.step('8. Click `Place your order and pay`', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeeOrderAccepted();
    orderId = orderCompletionPage.readOrderId();
  });

  await test.step('9. Open `Digital Wallet` from the account menu', async () => {
    await orderCompletionPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(balanceAfterOrder);
  });

  await test.step('10. Open `Order History` from the account menu', async () => {
    await walletPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrder({ orderId, totalPrice: orderTotal, bonus: orderBonus });
  });
});

