const startBasket: BasketLine[] = [{ product: productA, quantity: 1 }, { product: productB, quantity: 1 }];
const basketWithTwoA: BasketLine[] = [{ product: productA, quantity: 2 }, { product: productB, quantity: 1 }];
const basketWithoutA: BasketLine[] = [{ product: productB, quantity: 1 }];

test.use({ customerSetup: { basket: startBasket } });

test('Change the quantity and remove a product in the basket', {
