    await basketPage.open();
    await basketPage.shouldSeeLines(startBasket);
    await basketPage.shouldSeeTotalPrice(itemsTotal(startBasket));
    await basketPage.navbar.shouldSeeBasketCount(basketItemCount(startBasket));
