    await basketPage.shouldSeeLines(basketWithTwoA);
    await basketPage.shouldSeeTotalPrice(itemsTotal(basketWithTwoA));
    await basketPage.navbar.shouldSeeBasketCount(basketItemCount(basketWithTwoA));
