51	/**
52	 * The text must be right now and stay the same for the whole hold window.
53	 * A retrying assertion passes on the first right value and cannot show a later change.
54	 */
55	export async function expectTextHeld(locator: Locator, text: string, description: string): Promise<void> {
56	  await expectText(locator, text, description);
57	  const seen = new Set<string>();
58	  const start = Date.now();
59	  await expect
60	    .poll(
61	      async () => {
62	        seen.add((await locator.innerText()).trim());
63	        return Date.now() - start >= HOLD_WINDOW_MS;
64	      },
65	      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: HOLD_WINDOW_MS * 2 },
66	    )
67	    .toBe(true);
68	  expect([...seen], `${description} stays ${text} for ${HOLD_WINDOW_MS} ms`).toEqual([text]);
69	}
70	
71	/** The element must not appear during the whole hold window. */
72	export async function expectAbsentHeld(locator: Locator, description: string): Promise<void> {
73	  let shown = 0;
74	  const start = Date.now();
75	  await expect
76	    .poll(
77	      async () => {
78	        shown += await locator.count();
79	        return Date.now() - start >= HOLD_WINDOW_MS;
80	      },
81	      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: HOLD_WINDOW_MS * 2 },
82	    )
83	    .toBe(true);
84	  expect(shown, `${description} does not show for ${HOLD_WINDOW_MS} ms`).toBe(0);
85	}
