1	import { BasketLine, OrderTotals } from '@/utils/types/shop';
2	
3	/**
4	 * Expected values of the basket and the order, calculated from the catalog prices.
5	 * The coupon discount applies to the items only, not to the delivery.
6	 */
7	const CENTS = 100;
8	const BONUS_POINT_DIVISOR = 10;
9	
10	const roundToCents = (amount: number): number => Math.round(amount * CENTS) / CENTS;
11	
12	export function basketItemCount(lines: BasketLine[]): number {
13	  return lines.reduce((count, line) => count + line.quantity, 0);
14	}
15	
16	export function itemsTotal(lines: BasketLine[]): number {
17	  return roundToCents(lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0));
18	}
19	
20	export function orderTotals(lines: BasketLine[], deliveryPrice: number, discountPercent = 0): OrderTotals {
21	  const items = itemsTotal(lines);
22	  const promotion = roundToCents((items * discountPercent) / CENTS);
23	  return { items, delivery: deliveryPrice, promotion, total: roundToCents(items - promotion + deliveryPrice) };
24	}
25	
26	/** Bonus points of one product: price / 10, rounded to a whole number, × quantity. */
27	export function bonusPoints(lines: BasketLine[]): number {
28	  return lines.reduce((points, line) => points + Math.round(line.product.price / BONUS_POINT_DIVISOR) * line.quantity, 0);
29	}
