1	import { randomUUID } from 'node:crypto';
2	import { ShopApi } from '@/core/api/shop-api';
3	import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
4	import { Customer, CustomerSetup } from '@/utils/types/shop';
5	
6	/**
7	 * New customer accounts for tests: one unique account per test, created through the API,
8	 * with an optional basket, saved address and card, and wallet balance.
9	 */
10	const EMAIL_DOMAIN = 'example.test';
11	const UNIQUE_PART_LENGTH = 8;
12	
13	function uniquePart(): string {
14	  return `${Date.now()}-${randomUUID().slice(0, UNIQUE_PART_LENGTH)}`;
15	}
16	
17	export async function createCustomer(api: ShopApi, emailPrefix = 'customer'): Promise<Customer> {
18	  const unique = uniquePart();
19	  const email = `${emailPrefix}-${unique}@${EMAIL_DOMAIN}`;
20	  const password = `Passw0rd!${unique}`;
21	  await api.users.register(email, password);
22	  return api.users.login(email, password);
23	}
24	
25	export async function createPreparedCustomer(api: ShopApi, setup: CustomerSetup): Promise<Customer> {
26	  const customer = await createCustomer(api);
27	  for (const line of setup.basket ?? []) {
28	    const productId = await api.products.findProductId(line.product.name);
29	    await api.basket.addItem(customer, productId, line.quantity);
30	  }
31	  if (setup.savedAddressAndCard) {
32	    await api.payment.saveAddress(customer, SAVED_ADDRESS);
33	    customer.savedCardId = await api.payment.saveCard(customer, SAVED_CARD);
34	  }
35	  if (setup.walletBalance) {
36	    await addMoneyToWallet(api, customer, setup.walletBalance);
37	  }
38	  return customer;
39	}
40	
41	export async function addMoneyToWallet(api: ShopApi, customer: Customer, amount: number): Promise<void> {
42	  if (customer.savedCardId === undefined) {
43	    throw new Error('The shop adds money to the wallet only with a saved card. Set savedAddressAndCard first.');
44	  }
45	  await api.payment.topUpWallet(customer, amount, customer.savedCardId);
46	}
