2	export const CURRENCY_SIGN = '¤';
3	
4	const PRICE_DECIMALS = 2;
5	const BASKET_TOTAL_MAX_DECIMALS = 3;
6	
7	/** `8.99¤`, `0.00¤`: product, delivery and order summary prices. */
8	export function formatPrice(amount: number): string {
9	  return `${formatAmount(amount)}${CURRENCY_SIGN}`;
