import { Locator, Page } from '@playwright/test';
import { UI_TEXTS } from '@/utils/constants/ui-texts';
import { expectAbsentHeld, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

/** The panel `Add a coupon` on the payment page. */
export class CouponPanelComponent {
  private readonly panel: Locator;
  private readonly header: Locator;
  private readonly couponField: Locator;
  private readonly redeemButton: Locator;
  private readonly confirmationMessage: Locator;
  private readonly errorMessage: Locator;

  constructor(private readonly page: Page) {
    this.panel = page.locator('#collapseCouponElement');
    this.header = this.panel.locator('mat-expansion-panel-header');
    this.couponField = this.panel.locator('#coupon');
    this.redeemButton = this.panel.locator('#applyCouponButton');
    this.confirmationMessage = this.panel.locator('.confirmation');
    this.errorMessage = this.panel.locator('.error');
  }

  async shouldSeePanel(): Promise<void> {
    await expectVisible(this.header, 'Panel `Add a coupon`');
    await expectText(this.header.locator('mat-panel-title'), UI_TEXTS.addCouponPanel, 'Panel title');
  }

  async openPanel(): Promise<void> {
    await this.header.click();
    await expectVisible(this.couponField, 'Field `Coupon`');
  }

  /** Waits for the server answer: an old message with the same text can still be on the page. */
  async redeemCoupon(code: string): Promise<void> {
    await this.couponField.fill(code);
    const couponAnswer = this.page.waitForResponse(
      (response) => response.request().method() === 'PUT' && decodeURIComponent(response.url()).endsWith(code),
    );
    await this.redeemButton.click();
    await couponAnswer;
  }

  async shouldSeeDiscountMessage(percent: number): Promise<void> {
    await expectVisible(this.confirmationMessage, 'Coupon discount message');
    await expectText(this.confirmationMessage, UI_TEXTS.couponAccepted(percent), 'Coupon discount message');
  }

  async shouldSeeRejectedMessage(): Promise<void> {
    await expectVisible(this.errorMessage, 'Coupon error message');
    await expectText(this.errorMessage, UI_TEXTS.couponRejected, 'Coupon error message');
  }

  async shouldNotSeeDiscountMessage(): Promise<void> {
    await expectAbsentHeld(this.confirmationMessage, 'Coupon discount message');
  }
}

