import { expect, Locator, Page } from '@playwright/test';
import { DateHelper } from '@/utils/helpers/date-helper';
import { expectAbsentHeld, expectContainText, expectVisible } from '@/utils/assertions/ui-assertions';

const MESSAGE_CLOSE_TIMEOUT_MS = DateHelper.secondsToMs(15);

/** The message at the bottom of the page. The app marks it `confirmBar` or `errorBar`. */
export class SnackBarComponent {
  private readonly confirmation: Locator;
  private readonly error: Locator;

  constructor(page: Page) {
    this.confirmation = page.locator('mat-snack-bar-container.confirmBar');
    this.error = page.locator('mat-snack-bar-container.errorBar');
  }

  async shouldSeeConfirmation(text: string): Promise<void> {
    await expectVisible(this.confirmation, 'Confirmation message');
    await expectContainText(this.confirmation, text, 'Confirmation message');
  }

  async shouldSeeError(text: string): Promise<void> {
    await expectVisible(this.error, 'Error message');
    await expectContainText(this.error, text, 'Error message');
  }

  /** A new message can have the same text as an old one, so wait until the old one closes. */
  async waitForMessagesToClose(): Promise<void> {
    await expect(this.confirmation.or(this.error), 'Old messages close').toHaveCount(0, {
      timeout: MESSAGE_CLOSE_TIMEOUT_MS,
    });
  }

  async shouldNotSeeError(): Promise<void> {
    await expectAbsentHeld(this.error, 'Error message');
  }
}

