import { expect, Locator, Page } from '@playwright/test';
import { DateHelper } from '@/utils/helpers/date-helper';

/**
 * Assertion wrappers for page objects and helpers. Specs never call them directly.
 * Each one takes a description, so a failure says what was checked.
 */

/** How long a "does not change" or "does not show" check watches the UI. */
export const HOLD_WINDOW_MS = DateHelper.secondsToMs(2);
const HOLD_POLL_INTERVAL_MS = 200;

type TextExpectation = string | RegExp | Array<string | RegExp>;

export async function expectVisible(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is visible`).toBeVisible();
}

export async function expectHidden(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is hidden`).toBeHidden();
}

export async function expectText(locator: Locator, text: TextExpectation, description: string): Promise<void> {
  await expect(locator, `${description} has the text ${String(text)}`).toHaveText(text);
}

export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} contains ${String(text)}`).toContainText(text);
}

export async function expectNotContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} does not contain ${String(text)}`).not.toContainText(text);
}

export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
  await expect(locator, `${description}: count is ${count}`).toHaveCount(count);
}

export async function expectEnabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is enabled`).toBeEnabled();
}

export async function expectDisabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is disabled`).toBeDisabled();
}

/** A yes/no fact that a page object recorded, for example whether the server accepted a request. */
export function expectFlag(actual: boolean | undefined, expected: boolean, description: string): void {
  expect(actual, `${description}: ${expected}`).toBe(expected);
}

export async function expectUrl(page: Page, url: RegExp, description: string): Promise<void> {
  await expect(page, `${description}: URL matches ${url}`).toHaveURL(url);
}

/**
 * The text must be right now and stay the same for the whole hold window.
 * A retrying assertion passes on the first right value and cannot show a later change.
 */
export async function expectTextHeld(locator: Locator, text: string, description: string): Promise<void> {
  await expectText(locator, text, description);
  const seen = new Set<string>();
  const start = Date.now();
  await expect
    .poll(
      async () => {
        seen.add((await locator.innerText()).trim());
        return Date.now() - start >= HOLD_WINDOW_MS;
      },
      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: HOLD_WINDOW_MS * 2 },
    )
    .toBe(true);
  expect([...seen], `${description} stays ${text} for ${HOLD_WINDOW_MS} ms`).toEqual([text]);
}

/** The element must not appear during the whole hold window. */
export async function expectAbsentHeld(locator: Locator, description: string): Promise<void> {
  let shown = 0;
  const start = Date.now();
  await expect
    .poll(
      async () => {
        shown += await locator.count();
        return Date.now() - start >= HOLD_WINDOW_MS;
      },
      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: HOLD_WINDOW_MS * 2 },
    )
    .toBe(true);
  expect(shown, `${description} does not show for ${HOLD_WINDOW_MS} ms`).toBe(0);
}

