import { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { API_ROUTES, UI_ROUTES } from '@/utils/constants/routes';
import { formatBasketTotal, formatPrice } from '@/utils/helpers/price-format';
import { BasketLine } from '@/utils/types/shop';
import {
  expectCount,
  expectDisabled,
  expectText,
  expectTextHeld,
  expectUrl,
  expectVisible,
} from '@/utils/assertions/ui-assertions';

const BASKET_URL = /#\/basket$/;
const TOTAL_PRICE_PREFIX = 'Total Price: ';

/** The basket `/#/basket`. Each row: image, name, minus / quantity / plus, unit price, trash. */
export class BasketPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.locator('app-purchase-basket h1');
    this.rows = page.locator('app-purchase-basket mat-row');
    this.totalPrice = page.locator('app-purchase-basket #price');
    this.checkoutButton = page.locator('app-basket #checkoutButton');
  }

  /** Waits for the basket of the server: an empty table also shows before the basket loads. */
  async open(): Promise<void> {
    const basketLoaded = this.page.waitForResponse(
      (response) =>
        response.request().method() === 'GET' && new URL(response.url()).pathname.startsWith(API_ROUTES.basketPrefix),
    );
    await this.openRoute(UI_ROUTES.basket);
    await basketLoaded;
    await this.shouldSeePage();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, BASKET_URL, 'Basket page');
    await expectVisible(this.title, 'Basket title');
  }

  /** The basket shows exactly these rows, each with its quantity and unit price. */
  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.rows, lines.length, 'Basket rows');
    for (const line of lines) await this.shouldSeeLine(line);
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const row = this.row(line.product.name);
    await expectVisible(row, `Basket row ${line.product.name}`);
    await expectText(row.locator('mat-cell.mat-column-product'), line.product.name, `Name in the row ${line.product.name}`);
    await expectText(this.quantity(line.product.name), String(line.quantity), `Quantity of ${line.product.name}`);
    await expectText(row.locator('mat-cell.mat-column-price'), formatPrice(line.product.price), `Price of ${line.product.name}`);
  }

  /** The quantity is right and does not change during the hold window. */
  async shouldKeepQuantity(productName: string, quantity: number): Promise<void> {
    await expectTextHeld(this.quantity(productName), String(quantity), `Quantity of ${productName}`);
  }

  async shouldNotSeeProduct(productName: string): Promise<void> {
    await expectCount(this.row(productName), 0, `Basket rows of ${productName}`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.rows, 0, 'Basket rows');
  }

  async shouldSeeTotalPrice(amount: number): Promise<void> {
    await expectText(this.totalPrice, `${TOTAL_PRICE_PREFIX}${formatBasketTotal(amount)}`, 'Basket total');
  }

  async shouldKeepTotalPrice(amount: number): Promise<void> {
    await expectTextHeld(this.totalPrice, `${TOTAL_PRICE_PREFIX}${formatBasketTotal(amount)}`, 'Basket total');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
  }

  async clickIncreaseQuantity(productName: string): Promise<void> {
    await this.row(productName).locator('mat-cell.mat-column-quantity button').last().click();
  }

  async clickDecreaseQuantity(productName: string): Promise<void> {
    await this.row(productName).locator('mat-cell.mat-column-quantity button').first().click();
  }

  async clickRemove(productName: string): Promise<void> {
    await this.row(productName).locator('mat-cell.mat-column-remove button').click();
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  private row(productName: string): Locator {
    return this.rows.filter({ has: this.page.locator('mat-cell.mat-column-product', { hasText: productName }) });
  }

  private quantity(productName: string): Locator {
    return this.row(productName).locator('mat-cell.mat-column-quantity span.cell-initial-font');
  }
}

import { test } from '@/fixtures/customer.fixture';
import { checkoutWithSavedAddress, chooseDeliveryMethod } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  INVALID_COUPON_CODE,
  PRODUCTS,
  SAVED_ADDRESS,
  SAVED_CARD,
} from '@/utils/constants/shop-data';
import { previousMonthCouponCode } from '@/utils/helpers/coupon-code';
import { orderTotals } from '@/utils/helpers/order-math';
import { BasketLine } from '@/utils/types/shop';

const basket: BasketLine[] = [{ product: PRODUCTS.eggfruitJuice, quantity: 2 }];
const delivery = DELIVERY_METHODS.oneDay;

test.use({ customerSetup: { basket, savedAddressAndCard: true } });

test('The shop gives no discount for an invalid code and for a coupon of the previous month', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-06' },
}, async ({ basketPage, addressSelectPage, deliveryMethodPage, paymentPage, orderSummaryPage }) => {
  await test.step('1. Open the basket, check out and continue with the saved address', async () => {
    await checkoutWithSavedAddress(basketPage, addressSelectPage, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`2. Select \`${delivery.name}\` and continue`, async () => {
    await chooseDeliveryMethod(deliveryMethodPage, delivery.name);
    await paymentPage.shouldSeePage();
  });

  await test.step('3. Redeem the invalid code', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(INVALID_COUPON_CODE);
    await paymentPage.shouldSeeCouponRejected();
    await paymentPage.shouldNotSeeCouponDiscountMessage();
  });

  await test.step('4. Redeem the coupon of the previous month', async () => {
    await paymentPage.redeemCoupon(previousMonthCouponCode(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponRejected();
    await paymentPage.shouldNotSeeCouponDiscountMessage();
  });

  await test.step('5. Select the saved card and continue', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeLines(basket);
    await orderSummaryPage.shouldSeeTotals(orderTotals(basket, delivery.price));
  });
});

