import { test } from '@/fixtures/customer.fixture';
import { checkoutWithSavedAddress, chooseDeliveryMethod } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { COUPON_DISCOUNT_PERCENT, DELIVERY_METHODS, PRODUCTS, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
import { currentMonthCouponCode } from '@/utils/helpers/coupon-code';
import { DateHelper } from '@/utils/helpers/date-helper';
import { basketItemCount, itemsTotal, orderTotals } from '@/utils/helpers/order-math';
import { BasketLine } from '@/utils/types/shop';

const productA = PRODUCTS.eggfruitJuice;
const productB = PRODUCTS.carrotJuice;
const basket: BasketLine[] = [{ product: productA, quantity: 2 }, { product: productB, quantity: 1 }];
const delivery = DELIVERY_METHODS.oneDay;
const expectedTotals = orderTotals(basket, delivery.price, COUPON_DISCOUNT_PERCENT);

test.use({ customerSetup: { savedAddressAndCard: true } });

test('Order with a card and a coupon, from the basket to the order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({
  searchPage,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
}) => {
  // Ten UI steps through the whole checkout take longer than the default 30 s.
  test.setTimeout(DateHelper.minutesToMs(2));
  let orderId = '';

  await test.step('1. Add product A two times and product B one time from the product list', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(productA.name);
    await searchPage.clickAddToBasket(productA.name);
    await searchPage.clickAddToBasket(productB.name);
    await searchPage.navbar.shouldSeeBasketCount(basketItemCount(basket));
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeLines(basket);
    await basketPage.shouldSeeTotalPrice(itemsTotal(basket));
  });

  await test.step('3. Check out and continue with the saved address', async () => {
    await checkoutWithSavedAddress(basketPage, addressSelectPage, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step(`4. Select \`${delivery.name}\` and continue`, async () => {
    await chooseDeliveryMethod(deliveryMethodPage, delivery.name);
    await paymentPage.shouldSeePage();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(currentMonthCouponCode(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponDiscountMessage(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('6. Select the saved card and continue', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS);
    await orderSummaryPage.shouldSeeCardPayment(SAVED_CARD);
    await orderSummaryPage.shouldSeeLines(basket);
    await orderSummaryPage.shouldSeeTotals(expectedTotals);
  });

  await test.step('7. Click `Place your order and pay`', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeeOrderAccepted();
    orderId = orderCompletionPage.readOrderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeLines(basket);
    await orderCompletionPage.shouldSeeTotals(expectedTotals);
  });

  await test.step('9. Read the basket counter and open the basket', async () => {
    await orderCompletionPage.navbar.shouldSeeBasketCount(0);
    await basketPage.open();
    await basketPage.shouldSeeNoProducts();
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open `Order History` from the account menu', async () => {
    await basketPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrder({ orderId, totalPrice: expectedTotals.total, lines: basket });
  });
});

import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { APPLE_JUICE_PURCHASE_LIMIT, PRODUCTS } from '@/utils/constants/shop-data';
import { UI_TEXTS } from '@/utils/constants/ui-texts';
import { DateHelper } from '@/utils/helpers/date-helper';
import { basketItemCount, itemsTotal } from '@/utils/helpers/order-math';
import { BasketLine } from '@/utils/types/shop';

const product = PRODUCTS.appleJuice;
const basketAfterFirstAdd: BasketLine[] = [{ product, quantity: 1 }];
const basketAtLimit: BasketLine[] = [{ product, quantity: APPLE_JUICE_PURCHASE_LIMIT }];
const limitMessage = UI_TEXTS.purchaseLimitReached(APPLE_JUICE_PURCHASE_LIMIT);

test('A normal customer cannot put more than the purchase limit of a product into the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ searchPage, basketPage }) => {
  // Four quantity changes and eight "no change" holds take longer than the default 30 s.
  test.setTimeout(DateHelper.minutesToMs(2));

  await test.step(`1. Open the product list and add ${product.name} to the basket`, async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(product.name);
    await searchPage.snackBar.shouldSeeConfirmation(UI_TEXTS.placedIntoBasket(product.name));
    await searchPage.navbar.shouldSeeBasketCount(basketItemCount(basketAfterFirstAdd));
  });

  await test.step(`2. Open the basket and click plus until the quantity is ${APPLE_JUICE_PURCHASE_LIMIT}`, async () => {
    await basketPage.open();
    for (let quantity = 2; quantity <= APPLE_JUICE_PURCHASE_LIMIT; quantity += 1) {
      await basketPage.clickIncreaseQuantity(product.name);
      await basketPage.shouldSeeLine({ product, quantity });
      await basketPage.snackBar.shouldNotSeeError();
    }
    await basketPage.shouldSeeLines(basketAtLimit);
    await basketPage.shouldSeeTotalPrice(itemsTotal(basketAtLimit));
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickIncreaseQuantity(product.name);
    await basketPage.snackBar.shouldSeeError(limitMessage);
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.open();
    await basketPage.shouldKeepQuantity(product.name, APPLE_JUICE_PURCHASE_LIMIT);
    await basketPage.shouldKeepTotalPrice(itemsTotal(basketAtLimit));
    await basketPage.navbar.shouldKeepBasketCount(basketItemCount(basketAtLimit));
  });

  await test.step(`5. Open the product list and add ${product.name} to the basket again`, async () => {
    await searchPage.open();
    await searchPage.snackBar.shouldSeeNoMessages();
    await searchPage.clickAddToBasket(product.name);
    await searchPage.snackBar.shouldSeeError(limitMessage);
    await searchPage.navbar.shouldKeepBasketCount(basketItemCount(basketAtLimit));
  });
});

