1	import { expect, Locator, Page } from '@playwright/test';
2	import { DateHelper } from '@/utils/helpers/date-helper';
3	
4	/**
5	 * Assertion wrappers for page objects and helpers. Specs never call them directly.
6	 * Each one takes a description, so a failure says what was checked.
7	 */
8	
9	/** How long a "does not change" or "does not show" check watches the UI. */
10	export const HOLD_WINDOW_MS = DateHelper.secondsToMs(2);
11	const HOLD_POLL_INTERVAL_MS = DateHelper.secondsToMs(0.2);
12	
13	type TextExpectation = string | RegExp | Array<string | RegExp>;
14	
15	export async function expectVisible(locator: Locator, description: string): Promise<void> {
16	  await expect(locator, `${description} is visible`).toBeVisible();
17	}
18	
19	export async function expectHidden(locator: Locator, description: string): Promise<void> {
20	  await expect(locator, `${description} is hidden`).toBeHidden();
21	}
22	
23	export async function expectText(locator: Locator, text: TextExpectation, description: string): Promise<void> {
24	  await expect(locator, `${description} has the text ${String(text)}`).toHaveText(text);
25	}
26	
27	export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
28	  await expect(locator, `${description} contains ${String(text)}`).toContainText(text);
29	}
30	
31	export async function expectNotContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
32	  await expect(locator, `${description} does not contain ${String(text)}`).not.toContainText(text);
33	}
34	
35	export async function expectCount(locator: Locator, count: number, description: string, timeout?: number): Promise<void> {
36	  await expect(locator, `${description}: count is ${count}`).toHaveCount(count, { timeout });
37	}
38	
39	export async function expectEnabled(locator: Locator, description: string): Promise<void> {
40	  await expect(locator, `${description} is enabled`).toBeEnabled();
41	}
42	
43	export async function expectDisabled(locator: Locator, description: string): Promise<void> {
44	  await expect(locator, `${description} is disabled`).toBeDisabled();
45	}
46	
47	/** A yes/no fact that a page object recorded, for example whether the server accepted a request. */
48	export function expectFlag(actual: boolean | undefined, expected: boolean, description: string): void {
49	  expect(actual, `${description}: ${expected}`).toBe(expected);
50	}
51	
52	export async function expectUrl(page: Page, url: RegExp, description: string): Promise<void> {
53	  await expect(page, `${description}: URL matches ${url}`).toHaveURL(url);
54	}
55	
56	/**
57	 * The text must be right now and stay the same for the whole hold window.
58	 * A retrying assertion passes on the first right value and cannot show a later change.
59	 */
60	export async function expectTextHeld(locator: Locator, text: string, description: string): Promise<void> {
61	  await expectText(locator, text, description);
62	  const seen = new Set<string>();
63	  const start = Date.now();
64	  await expect
65	    .poll(
66	      async () => {
67	        seen.add((await locator.innerText()).trim());
68	        return Date.now() - start >= HOLD_WINDOW_MS;
69	      },
70	      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: HOLD_WINDOW_MS * 2 },
71	    )
72	    .toBe(true);
73	  expect([...seen], `${description} stays ${text} for ${HOLD_WINDOW_MS} ms`).toEqual([text]);
74	}
75	
76	/** The element must not appear during the whole hold window. */
77	export async function expectAbsentHeld(locator: Locator, description: string): Promise<void> {
78	  let shown = 0;
79	  const start = Date.now();
80	  await expect
81	    .poll(
82	      async () => {
83	        shown += await locator.count();
84	        return Date.now() - start >= HOLD_WINDOW_MS;
85	      },
86	      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: HOLD_WINDOW_MS * 2 },
87	    )
88	    .toBe(true);
89	  expect(shown, `${description} does not show for ${HOLD_WINDOW_MS} ms`).toBe(0);
90	}
