1	import { encode } from 'z85';
2	
3	/**
4	 * Coupon codes of test-cases/README.md: the Z85 encoding of `<MMM><YY>-<NN>`.
5	 * The server checks the month in its local time, and the tests run on the same machine,
6	 * so the code uses the local date of this machine.
7	 */
8	const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
9	
10	function couponCodeForMonth(monthDate: Date, discountPercent: number): string {
11	  const month = MONTHS[monthDate.getMonth()];
12	  const year = String(monthDate.getFullYear()).slice(-2);
13	  const discount = String(discountPercent).padStart(2, '0');
14	  const code = encode(`${month}${year}-${discount}`);
15	  if (!code) throw new Error(`Cannot encode a coupon for ${month}${year}-${discount}`);
16	  return code;
17	}
18	
19	export function currentMonthCouponCode(discountPercent: number, now = new Date()): string {
20	  return couponCodeForMonth(now, discountPercent);
21	}
22	
23	export function previousMonthCouponCode(discountPercent: number, now = new Date()): string {
24	  return couponCodeForMonth(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
25	}
